16	
17	    /** The Luhn check digit for the given owner, or null when it has no customer code. */
18	    public static Integer of(Owner owner) {
19	        String customerCode = owner.getCustomerCode();
20	        if (customerCode == null) {
21	            return null;
22	        }
23	        int sum = 0;
24	        boolean dbl = true;
25	        for (int i = customerCode.length() - 1; i >= 0; i--) {
26	            char c = customerCode.charAt(i);
27	            if (c < '0' || c > '9') {
28	                continue;
29	            }
30	            int d = c - '0';
31	            if (dbl) {
32	                d *= 2;
33	                if (d > 9) {
34	                    d -= 9;
35	                }
36	            }
37	            sum += d;
38	            dbl = !dbl;
39	        }
40	        return (10 - (sum % 10)) % 10;
