3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Rolls a registration date forward onto a business day. A Saturday or Sunday is
8	 * rolled forward to the next Monday; a weekday is returned unchanged. Shared by
9	 * {@link BuildOwner} (which stores the adjusted date, so every value derived from it
10	 * — such as the membership number's year segment — uses the business day) and
11	 * {@link CheckOwnerDailyLimit} (which counts owners per adjusted business day).
12	 */
13	final class BusinessDay {
14	
15	    private BusinessDay() {
16	    }
17	
18	    /** Returns {@code date} if it is a weekday, else the next Monday. */
19	    static LocalDate adjust(LocalDate date) {
20	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
21	            date = date.plusDays(1);
22	        }
23	        return date;
24	    }
25	}
