package org.springframework.samples.petclinic.model;

import java.util.Map;
import java.util.regex.Pattern;

/**
 * Validates a 4-digit postcode against the fixed region ranges derived from an owner's
 * city (see {@link Locality}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A city with
 * no known region accepts any 4-digit postcode.
 */
public final class Postcode {

    /** A postcode must be exactly four digits. */
    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    private Postcode() {
    }

    /**
     * Whether {@code postcode} is valid for {@code city}: it must be exactly four digits and,
     * when the city maps to a known region, fall within that region's inclusive range. A city
     * with no known region accepts any 4-digit postcode.
     */
    public static boolean isValidForCity(String postcode, String city) {
        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
            return false;
        }
        int[] range = REGION_RANGE.get(Locality.of(city));
        if (range == null) {
            return true;
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }
}
===== model/MembershipLevel =====
package org.springframework.samples.petclinic.model;

/**
 * Derives an owner's numeric membership level, assigned at creation.
 *
 * <p>Starts at 1; add 1 when an email is present; add 1 when {@code namesakeCount}
 * is 0; capped at 3. Level 4 is reserved for tenure.
 */
public final class MembershipLevel {

    /** The maximum level assignable at creation; level 4 is reserved for tenure. */
    public static final int MAX = 3;

    private MembershipLevel() {
    }

    /** The membership level for the given owner. */
    public static int of(Owner owner) {
        int level = 1;
        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
            level++;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            level++;
        }
        return Math.min(level, MAX);
    }
}
===== model/IdentityKey =====
package org.springframework.samples.petclinic.model;

/**
 * Derives an owner's {@code identityKey}: the single value all duplicate detection is
 * expressed through.
 *
 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
 * By the time an owner is built its telephone has been normalized to E.164 and its email
 * lower-cased, so those stored values are the normalized forms. A null email or a null
 * {@code householdId} contributes an empty segment.
 *
 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal. Because the
 * telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones have different keys and are both allowed.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    /** The identity key for the given owner. */
    public static String of(Owner owner) {
        return segment(owner.getTelephone()) + "|" + segment(owner.getEmail()) + "|"
                + segment(owner.getHouseholdId());
    }

    private static String segment(String value) {
        return value == null ? "" : value;
    }
}
