9	/**
10	 * The single duplicate-detection step. Rejects a create request whose owner has the same
11	 * {@code identityKey} as an existing owner. The key consolidates what used to be three
12	 * separate checks (telephone, email and household), so a create is a duplicate only when
13	 * its <em>whole</em> key matches — telephone <em>and</em> email <em>and</em> household.
14	 *
15	 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold} so the new owner carries
16	 * its normalized telephone/email and its assigned {@code householdId}, and before
17	 * {@link SaveOwner} so a duplicate is a 409 rather than a persisted record. Because the
18	 * telephone is part of the key, two members of the same household with different
19	 * telephones have different keys and are both allowed.
20	 */
21	public class CheckOwnerIdentityUnique {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws OwnerIdentityConflictException {
25	        String identityKey = IdentityKey.of(owner);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (identityKey.equals(IdentityKey.of(existing))) {
28	                throw new OwnerIdentityConflictException(identityKey);
29	            }
30	        }
31	    }
32	}
