14	 * {@link BuildOwner} runs. Reads the body once and republishes it for later steps.
15	 */
16	public class ValidateOwnerFields {
17	
18	    /** A syntactically valid address: local-part@domain with a dotted domain, no spaces. */
19	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
20	
21	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
22	            throws OwnerFieldsInvalidException {
23	        List<String> errors = new ArrayList<>();
24	        checkRequired("firstName", request.getFirstName(), errors);
25	        checkRequired("lastName", request.getLastName(), errors);
26	        checkRequired("city", request.getCity(), errors);
27	        checkRequired("telephone", request.getTelephone(), errors);
28	        normalizeAddress(request, errors);
29	        normalizeTelephone(request, errors);
30	        normalizeEmail(request, errors);
31	        validatePostcode(request, errors);
32	        if (!errors.isEmpty()) {
33	            throw new OwnerFieldsInvalidException(errors);
34	        }
35	        validated.set(request);
36	    }
37	
38	    private static void checkRequired(String field, String value, List<String> errors) {
39	        if (value == null || value.isBlank()) {
40	            errors.add(field);
41	        }
42	    }
43	
44	    /**
45	     * Normalizes the address (see {@link AddressNormalizer}) and stores the result back on
46	     * the request so later steps persist, compare and return the canonical form. The
47	     * address is required: a value that is blank after normalization is a 400 (adds an
48	     * "address" error) and is not stored back.
49	     */
50	    private static void normalizeAddress(OwnerFieldsDto request, List<String> errors) {
51	        String normalized = AddressNormalizer.normalize(request.getAddress());
52	        if (normalized.isEmpty()) {
53	            errors.add("address");
54	        }
55	        else {
56	            request.setAddress(normalized);
57	        }
58	    }
59	
60	    /**
61	     * Normalizes the telephone to E.164 form (see {@link TelephoneE164}), storing the
62	     * result back on the request so later steps persist and return it. A value that
63	     * cannot form a valid E.164 number is a 400 (adds a "telephone" error).
64	     */
65	    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
66	        String telephone = request.getTelephone();
67	        if (telephone == null) {
68	            return;
69	        }
70	        String e164 = TelephoneE164.toE164(telephone);
71	        if (e164 != null) {
72	            request.setTelephone(e164);
73	        }
74	        else if (!errors.contains("telephone")) {
75	            errors.add("telephone");
76	        }
77	    }
78	
79	    /**
80	     * Email is optional. When present (non-blank) it must be a syntactically valid address;
81	     * an invalid value is a 400 (adds an "email" error). A valid value is stored lower-cased
82	     * back on the request so later steps persist and return it lower-cased.
83	     */
84	    private static void normalizeEmail(OwnerFieldsDto request, List<String> errors) {
85	        String email = request.getEmail();
86	        if (email == null || email.isBlank()) {
87	            return;
88	        }
89	        String trimmed = email.trim();
90	        if (EMAIL.matcher(trimmed).matches()) {
91	            request.setEmail(trimmed.toLowerCase());
92	        }
93	        else if (!errors.contains("email")) {
94	            errors.add("email");
95	        }
96	    }
97	
98	    /**
99	     * Postcode is optional. When present (non-blank) it must be a 4-digit value that is valid
100	     * for the owner's city per the fixed region ranges (see
101	     * {@link org.springframework.samples.petclinic.model.Postcode}); an out-of-range or
102	     * malformed value is a 400 (adds a "postcode" error). A valid value is stored trimmed back
103	     * on the request so later steps persist and return it. A city with no known region accepts
104	     * any 4-digit postcode, keeping the create request backward-compatible when absent.
105	     */
106	    private static void validatePostcode(OwnerFieldsDto request, List<String> errors) {
107	        String postcode = request.getPostcode();
108	        if (postcode == null || postcode.isBlank()) {
109	            return;
110	        }
111	        String trimmed = postcode.trim();
112	        if (org.springframework.samples.petclinic.model.Postcode.isValidForCity(trimmed, request.getCity())) {
113	            request.setPostcode(trimmed);
114	        }
115	        else if (!errors.contains("postcode")) {
116	            errors.add("postcode");
117	        }
118	    }
119	}
